int runBeatThis550(){juce::ScopedJuceInitialiser_GUI gui;LibraryPreparation::checksPaused=true;try{auto require=[](bool ok,const char* why){if(!ok)throw std::runtime_error(why);};Processor decoder(false);decoder.autoSave=false;auto file=juce::File::getCurrentWorkingDirectory().getChildFile("work/stem-comparison/roy-input.wav");auto data=decoder.readAudio(file);require(data!=nullptr,"real audio fixture");auto start=juce::Time::getMillisecondCounterHiRes();bool sawProgress=false;float lastProgress=0;auto grid=TrackAnalyser::analyse(*data,50,200,{},[&](float value){require(value>=lastProgress,"progress must not go backwards");lastProgress=value;sawProgress|=value>.15f&&value<.95f;});require(sawProgress&&lastProgress==1,"live model-window progress reaches completion");require(grid.detector=="Beat This small small0"&&grid.anchors.size()>15&&grid.analysisWarning.isEmpty(),"native small model required, no legacy fallback");require(grid.bpm>50&&grid.bpm<200&&grid.calibrationMs==0,"model tempo and no legacy calibration");std::cout<<"Small model: "<<grid.anchors.size()<<" beats, "<<grid.bpm<<" BPM, "<<(juce::Time::getMillisecondCounterHiRes()-start)/1000<<" seconds for 20s real audio\n";
 auto cache=LibraryStore::root().getChildFile("neural.xml");TrackAnalyser::saveCache(cache,50,200,grid);TrackGrid recalled;require(TrackAnalyser::loadCache(cache,*data,50,200,recalled)&&recalled.detector==grid.detector&&recalled.anchors.size()==grid.anchors.size(),"versioned model cache roundtrip");auto legacy=juce::XmlDocument::parse(cache);legacy->removeAttribute("detector");legacy->writeTo(cache);require(!TrackAnalyser::loadCache(cache,*data,50,200,recalled),"legacy automatic cache must not mask small model");
 auto straight=TrackAnalyser::analyseStraight(*data,50,200,8000);require(straight.detector==grid.detector&&straight.straight&&straight.analysed.size()>10&&straight.bpm>50&&straight.bpm<200,"neural straight fit with offset");
 TrackGrid edited=grid;edited.put(edited.sampleAt(8,data->rate)+100,8,data->rate);edited.beatOffset=1;edited.downbeatOffset=50;auto replacement=grid;require(TrackAnalyser::preserveManual550(replacement,edited)&&replacement.manual.size()==edited.manual.size()&&replacement.beatOffset==1&&replacement.downbeatOffset==50&&replacement.manual[0].sample==edited.manual[0].sample,"manual anchors and offsets retained");
 Processor p(false);p.autoSave=false;p.audio=data;p.split(2,false);p.trackMode=p.stretchMode=true;p.trackGrid=edited;p.trackGridReady=p.trackGridEdited=true;auto state=p.configurationXml(true);Processor restored(false);restored.autoSave=false;restored.trackOffline=true;restored.audio=data;require(restored.applyConfiguration(*state,true)&&restored.trackGrid.detector==grid.detector&&restored.trackGrid.manual.size()==edited.manual.size(),"manual neural grid Set recall");
 TrackGrid precise;precise.detector="Beat This small small0";precise.anchors.clear();for(int i=0;i<500;++i)precise.anchors.push_back({std::round((i*60/123.45)/.02)*.02*44100,(double)i});precise.autoChooseMode(44100);require(precise.straight&&std::abs(precise.bpm-123.45)<.002,"stable neural grids avoid long-track BPM drift");
 int polls=0;start=juce::Time::getMillisecondCounterHiRes();auto cancelled=TrackAnalyser::analyse(*data,50,200,[&]{++polls;return juce::Time::getMillisecondCounterHiRes()-start>250;});require(cancelled.anchors.size()<2&&juce::Time::getMillisecondCounterHiRes()-start<3000,"cancellation kills helper without fallback work");
 std::cout<<"Small Beat This small0, cache isolation, straight/offset fitting, manual edits/Set recall and cancellation passed\n";return 0;
 }catch(const std::exception& error){std::cerr<<"BeatThis550: "<<error.what()<<"\n";return 2550;}}
